```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT (c.duration>100000000) slow, (SELECT count(*) FROM abnormal_traces t WHERE t.parent_span_id=c.span_id)>0 has_kid, count(*) n, avg(c.duration)/1e6 avgms FROM abnormal_traces c WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' AND c.span_name='GET' GROUP BY 1,2", "claim": "Seat-service's outgoing GET calls are slow (avg 212-635ms) in a subset of calls, while fast ones average about 3ms."},
        {"kind": "trace", "sql": "SELECT c.duration/1e6 cms, t.duration/1e6 kidms, t.service_name FROM abnormal_traces c JOIN abnormal_traces t ON t.parent_span_id=c.span_id WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' AND c.span_name='GET' AND c.duration>100000000 ORDER BY c.time", "claim": "For slow seat GET calls to ts-config-service, the config server span itself takes only about 3ms, so the extra ~200ms is before the server handles the request."},
        {"kind": "trace", "sql": "SELECT t.service_name callee, cl.service_name caller, cl.span_name, t.attr_span_kind FROM abnormal_traces t JOIN abnormal_traces cl ON t.parent_span_id=cl.span_id AND t.trace_id=cl.trace_id WHERE t.service_name='ts-config-service' AND cl.service_name IN ('ts-seat-service','ts-admin-basic-info-service') LIMIT 5", "claim": "Only seat's GET path to config is slowed; admin-basic-info's calls to config-service stay at about 4-5ms."},
        {"kind": "trace", "sql": "SELECT approx_quantile(duration,0.95)/1e6 p95ms, avg(duration)/1e6 avgms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='POST /api/v1/seatservice/seats/left_tickets' AND attr_span_kind='Server'", "claim": "Seat-service left_tickets server p95 is about 431ms in the abnormal period, versus about 13ms in normal."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-seat-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT s.service_name callee, cl.service_name caller, count(*) n, sum(CASE WHEN s.duration>100000000 THEN 1 ELSE 0 END) slow_gt100ms, approx_quantile(s.duration,0.95)/1e6 srv_p95 FROM abnormal_traces s JOIN abnormal_traces cl ON s.parent_span_id=cl.span_id AND s.trace_id=cl.trace_id WHERE s.attr_span_kind='Server' AND s.service_name='ts-seat-service' AND cl.service_name='ts-travel-plan-service' GROUP BY 1,2", "claim": "Travel-plan's calls to seat-service's left_tickets: 5 of 21 exceed 100ms, p95 about 854ms."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT s.span_name, count(*) n, approx_quantile(s.duration,0.95)/1e6 srv_p95 FROM abnormal_traces s WHERE s.service_name='ts-travel-plan-service' AND s.attr_span_kind='Server' AND s.span_name LIKE '%travelPlan%' GROUP BY 1", "claim": "Travel-plan's user-facing cheapest endpoint p95 rises to about 4.1s, quickest to about 2.3s, from about 107ms and 125ms in normal."}]}
  ]
}
